DROP POLICY IF EXISTS "Clínicas pueden ver sus propios registros de ortodoncia" ON orthodontics_records;
CREATE POLICY "Clínicas pueden ver sus propios registros de ortodoncia"
ON orthodontics_records FOR ALL
TO authenticated
USING (
    EXISTS (
        SELECT 1 FROM patients
        WHERE patients.id::text = orthodontics_records.patient_id::text
        AND patients.admin_email = (SELECT auth.email())
    )
)
WITH CHECK (
    EXISTS (
        SELECT 1 FROM patients
        WHERE patients.id::text = orthodontics_records.patient_id::text
        AND patients.admin_email = (SELECT auth.email())
    )
);

